// A tiny fake clock, and why promises are not part of it.
class FakeClock {
  constructor() { this.now = 0; this.timers = []; }
  setTimeout(fn, ms) { this.timers.push({ at: this.now + ms, fn }); }
  advance(ms) {                       // synchronous advance
    const target = this.now + ms;
    for (;;) {
      this.timers.sort((a, b) => a.at - b.at);
      const t = this.timers[0];
      if (!t || t.at > target) break;
      this.timers.shift();
      this.now = t.at;                // jump the clock to the timer time
      t.fn();                         // may add more timers
    }
    this.now = target;
  }
  async advanceAsync(ms) {            // flush microtasks first
    await Promise.resolve();
    this.advance(ms);
  }
}
const log = [];
async function retryLater(clock) {
  await Promise.resolve();            // like await fetch()
  clock.setTimeout(() => log.push('retry fired'), 1000);
}
(async () => {
