  retryLater(c1);
  c1.advance(1000);                   // timer not scheduled yet
  console.log('sync advance  ->', log.length, 'timers fired');
  await Promise.resolve(); await Promise.resolve();
  console.log('timers pending after microtasks:', c1.timers.length);
