async function fakeFetch(url, opts = {}) {      // the "network edge"
  const method = opts.method || 'GET';
  const h = handlers.find(x => x.method === method && x.path === url);
  if (!h) throw new Error('unhandled request ' + method + ' ' + url);
  const { status, body } = h.resolver();
  return { ok: status < 400, status, json: async () => body };
}
