// Task: return the two values that sum to target, as indices (first match).
function twoSum(nums, target) {
  const seen = new Map();                       // value -> index, O(n) time/space
  for (let i = 0; i < nums.length; i++) {
    if (seen.has(target - nums[i])) return [seen.get(target - nums[i]), i];
    seen.set(nums[i], i);
  }
  return null;
}
