// A mini snapshot matcher with property matchers and --ci behaviour.
const store = {};                               // stands in for the .snap file
const any = typeof_ => ({ __any: typeof_ });
function toMatchSnapshot(name, value, props = {}, ci = false) {
  const copy = JSON.parse(JSON.stringify(value));
  for (const k in props) {                      // replace unstable fields
    if (typeof copy[k] === props[k].__any) copy[k] = '<' + props[k].__any + '>';
  }
  const text = JSON.stringify(copy);
  if (!(name in store)) {
    if (ci) return 'FAIL: no snapshot written in --ci mode';
    store[name] = text; return 'written';
  }
  return store[name] === text ? 'pass' : 'FAIL: expected ' + store[name] + ' got ' + text;
}
